                    prog_next = data ? 2'd1 : 2'd3;
                end else begin
                    // prog == 3 (matched "110")
                    // Next bit completes pattern if data==1
                    // If data==0, no prefix of 1101 matches because last bit is 0.
                    prog_next = data ? 2'd0 : 2'd0;
                end

                // Detect full pattern 1101: prog==3 and data==1
                if ((prog == 2'd3) && data) begin
                    state_next = S_SHIFT;
                    cnt_next   = 2'd0;
                    prog_next  = 2'd0;
                end",
    "new_content": "                // Corrected prefix progress for detecting serial 1101.
                // prog meanings:
                // 0: matched ""
                // 1: matched "1"
                // 2: matched "11"
                // 3: matched "110"
                if (prog == 2'd0) begin
                    prog_next = data ? 2'd1 : 2'd0;
                end else if (prog == 2'd1) begin
                    prog_next = data ? 2'd2 : 2'd0;
                end else if (prog == 2'd2) begin
                    // On data=1, the suffix "11" is maintained.
                    // On data=0, the suffix becomes "110".
                    prog_next = data ? 2'd2 : 2'd3;
                end else begin
                    // prog == 2'd3 (matched "110")
                    // On data=1, full pattern 1101 detected.
                    // On data=0, suffix ends with "0" which doesn't match any non-empty prefix of 1101.
                    prog_next = 2'd0;
                end

                // Detect full pattern 1101: current prefix "110" and current bit 1.
                if ((prog == 2'd3) && data) begin
                    state_next = S_SHIFT;
                    cnt_next   = 2'd0;
                    prog_next  = 2'd0;
                end"
  }
}
